quests[29014] = { id = 29014, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket", sourceObjective = "Candy buckets like this are located in inns throughout the realms. Go ahead... take some!", sourceObjectiveStatus = "unverified-source-field" }
quests[29015] = { id = 29015, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Miner's Fortune", description = "Hey {race}, you interested in treasure? I knew that would get your attention.\n\nWord from the river dock here is that one of the miners in the Venture Company's Boulder Lode mine just northeast of here discovered an emerald the size of your fist.\n\nI know a few buyers who'd be interested in getting their hands on something like that, and I'd be willing to go half and half on its sale. You in?", sourceObjective = "Retrieve the Cats Eye Emerald from one of the Venture Co. Overseers or Enforcers.", progress = "If only we knew which one of the miners had found the emerald, it'd be a walk in the park...", completion = "Look at the size of that thing! We're going to be rich! Let's see, according to the rates I've seen on gems going into Undermine, I should be able to figure out your cut - fifty percent, don't worry!\n\nNow let's see... I think this should do about right. Pleasure doing business with you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29016] = { id = 29016, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket", sourceObjective = "Candy buckets like this are located in inns throughout the realms. Go ahead... take some!", sourceObjectiveStatus = "unverified-source-field" }
